#!/bin/sh
# 预处理是文本包含：为什么一个头文件改动会波及所有包含它的 .c
# 期望输出见 expected_output（本机 MinGW 工具链 + GNU Make 真实执行捕获）

cat > util.h << 'EOF'
int add(int a, int b);
EOF

cat > util.c << 'EOF'
#include "util.h"

int add(int a, int b)
{
    return a + b;
}
EOF

cat > main.c << 'EOF'
#include <stdio.h>
#include "util.h"

int main(void)
{
    printf("add(2, 3) = %d\n", add(2, 3));
    return 0;
}
EOF

wc -l main.c util.h
gcc -E main.c -o main.i
wc -l main.i            # 展开后行数：stdio.h + util.h 的内容都进来了
grep -n 'int add' main.i   # 头文件里的声明出现在 main.i 中（文本复制）
gcc -E util.c -o util.i
grep -c 'int add' util.i   # util.i 里也有同一份声明
